from pathlib import Path
import json,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
H=Path(__file__).resolve().parent;D=H/'cad_rgbd_odometry';r=json.loads((D/'predictions.json').read_text());a=json.loads((D/'support_layer_diagnosis.json').read_text())['frames'];t=[x['time_s'] for x in r];fig,ax=plt.subplots(2,1,figsize=(10,7));ax[0].plot(t,[x['full_support_ORB'] for x in a],label='Full-mask-support ORB features');ax[0].plot(t,[x['final_selfdistance_after_precision'] for x in a],label='Feature pixels with qualified previous metric depth');ax[0].legend();ax[0].set_ylabel('Feature count');ax[1].plot(t[1:],[x['landmarks'] for x in r[1:]],label='Cross-frame metric common landmarks');ax[1].axhline(8,c='red',ls='--',label='Frozen minimum8');ax[1].scatter([x['time_s'] for x in r[1:] if x['accepted']],[x['landmarks'] for x in r[1:] if x['accepted']],c='green',label='Local increment accepted (chain remains unknown)');ax[1].legend();ax[1].set_xlabel('simulation s');ax[1].set_ylabel('Common landmarks');fig.suptitle('REJECT: chain lost at0.5s; coverage1/25 initial gauge only');fig.tight_layout();fig.savefig(D/'source_support_and_common_landmarks.png',dpi=140)
